import fs from 'fs';

const dgPath = 'data/dual_gate_database.json';
const db = JSON.parse(fs.readFileSync(dgPath, 'utf8'));

console.log('Original record count:', db.length);
// Remove test records generated by automated test scripts
const cleaned = db.filter(r => !r.idPenugasan.startsWith('NSR-TEST-') && !r.idPenugasan.startsWith('TEST-'));
console.log('Cleaned record count:', cleaned.length);

fs.writeFileSync(dgPath, JSON.stringify(cleaned, null, 2));
console.log('Cleaned test records from dual_gate_database.json');
